description:
Write the camera maths for a 2D editor viewport:

```cpp
struct Vec2 { float x, y; };
struct Camera { Vec2 pan{ 0, 0 }; float zoom{ 32 }; };     // zoom: pixels per tile

Vec2 tileToScreen(const Camera& c, Vec2 origin, Vec2 tile);
Vec2 screenToTile(const Camera& c, Vec2 origin, Vec2 screen);
void zoomAround(Camera& c, Vec2 origin, Vec2 mouse, float factor, float minZoom, float maxZoom);
void visibleTiles(const Camera& c, Vec2 origin, Vec2 size, int mapW, int mapH, int& x0, int& y0, int& x1, int& y1);
```

- `tileToScreen`: `origin + pan + tile * zoom` (for each of x and y).
- `screenToTile`: the reverse: `(screen - origin - pan) / zoom`.
- `zoomAround`: multiply the zoom by `factor`, clamped to `minZoom..maxZoom`, and change `pan` so that the point under `mouse` (in tile coordinates, before the zoom) is still under `mouse` afterwards.
- `visibleTiles`: the range of **whole** tiles that touch the viewport rectangle (`origin` to `origin + size`): `x0 = floor` of the left edge in tiles, `x1 = ceil` of the right edge (exclusive end), likewise for y, each clamped to `0..mapW` or `0..mapH`.

starter.solution.cpp:
#include <cmath>

struct Vec2 { float x, y; };
struct Camera { Vec2 pan{ 0, 0 }; float zoom{ 32 }; };

Vec2 tileToScreen(const Camera& c, Vec2 origin, Vec2 tile) { return { 0, 0 }; }
Vec2 screenToTile(const Camera& c, Vec2 origin, Vec2 screen) { return { 0, 0 }; }
void zoomAround(Camera& c, Vec2 origin, Vec2 mouse, float factor, float minZoom, float maxZoom) {}
void visibleTiles(const Camera& c, Vec2 origin, Vec2 size, int mapW, int mapH, int& x0, int& y0, int& x1, int& y1) { x0 = y0 = x1 = y1 = 0; }

solution.solution.cpp:
#include <algorithm>
#include <cmath>

struct Vec2 { float x, y; };
struct Camera { Vec2 pan{ 0, 0 }; float zoom{ 32 }; };

Vec2 tileToScreen(const Camera& c, Vec2 origin, Vec2 tile)
{
    return { origin.x + c.pan.x + tile.x * c.zoom, origin.y + c.pan.y + tile.y * c.zoom };
}

Vec2 screenToTile(const Camera& c, Vec2 origin, Vec2 screen)
{
    return { (screen.x - origin.x - c.pan.x) / c.zoom, (screen.y - origin.y - c.pan.y) / c.zoom };
}

void zoomAround(Camera& c, Vec2 origin, Vec2 mouse, float factor, float minZoom, float maxZoom)
{
    const Vec2 under{ screenToTile(c, origin, mouse) };
    c.zoom = std::clamp(c.zoom * factor, minZoom, maxZoom);
    c.pan.x = mouse.x - origin.x - under.x * c.zoom;
    c.pan.y = mouse.y - origin.y - under.y * c.zoom;
}

void visibleTiles(const Camera& c, Vec2 origin, Vec2 size, int mapW, int mapH, int& x0, int& y0, int& x1, int& y1)
{
    const Vec2 a{ screenToTile(c, origin, origin) };
    const Vec2 b{ screenToTile(c, origin, { origin.x + size.x, origin.y + size.y }) };
    x0 = std::clamp(static_cast<int>(std::floor(a.x)), 0, mapW);
    y0 = std::clamp(static_cast<int>(std::floor(a.y)), 0, mapH);
    x1 = std::clamp(static_cast<int>(std::ceil(b.x)), 0, mapW);
    y1 = std::clamp(static_cast<int>(std::ceil(b.y)), 0, mapH);
}

unitTests:
bool near2(Vec2 v, float x, float y) { return std::fabs(v.x - x) < 1e-3f && std::fabs(v.y - y) < 1e-3f; }
TEST("tile to screen") { Camera c{ { 10, 20 }, 32 }; CHECK(near2(tileToScreen(c, { 100, 50 }, { 2, 3 }), 174, 166)); }
TEST("and back") { Camera c{ { 10, 20 }, 32 }; CHECK(near2(screenToTile(c, { 100, 50 }, { 174, 166 }), 2, 3)); CHECK(near2(screenToTile(c, { 100, 50 }, { 190, 182 }), 2.5f, 3.5f)); }
TEST("zoom keeps the point under the mouse") {
    Camera c{ { 10, 20 }, 32 }; const Vec2 origin{ 100, 50 }, mouse{ 300, 200 };
    const Vec2 before = screenToTile(c, origin, mouse);
    zoomAround(c, origin, mouse, 2.0f, 4, 256);
    CHECK_NEAR(c.zoom, 64.0, 1e-4); CHECK(near2(screenToTile(c, origin, mouse), before.x, before.y));
}
TEST("zoom is clamped") { Camera c{ { 0, 0 }, 200 }; zoomAround(c, { 0, 0 }, { 50, 50 }, 4.0f, 4, 256); CHECK_NEAR(c.zoom, 256.0, 1e-4); zoomAround(c, { 0, 0 }, { 50, 50 }, 0.001f, 4, 256); CHECK_NEAR(c.zoom, 4.0, 1e-4); }
TEST("visible tiles") {
    Camera c{ { -48, -16 }, 32 }; int x0, y0, x1, y1;
    visibleTiles(c, { 0, 0 }, { 100, 64 }, 40, 24, x0, y0, x1, y1);
    CHECK_EQ(x0, 1); CHECK_EQ(y0, 0); CHECK_EQ(x1, 5); CHECK_EQ(y1, 3);
}
TEST("visible tiles are clamped to the map") { Camera c{ { 500, 500 }, 32 }; int x0, y0, x1, y1; visibleTiles(c, { 0, 0 }, { 100, 100 }, 10, 10, x0, y0, x1, y1); CHECK_EQ(x0, 0); CHECK_EQ(x1, 0); Camera d{ { -1000, 0 }, 32 }; visibleTiles(d, { 0, 0 }, { 100, 100 }, 10, 10, x0, y0, x1, y1); CHECK_EQ(x0, 10); CHECK_EQ(x1, 10); }

